import sys

def transform(grid):
    H = len(grid)
    W = len(grid[0]) if H else 0

    def in_bounds(r, c):
        return 0 <= r < H and 0 <= c < W

    # Find connected components made of 1s and 3s.
    comp_id = [[-1] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] in (1, 3) and comp_id[r][c] == -1:
                cells = []
                stack = [(r, c)]
                comp_id[r][c] = len(components)
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if in_bounds(nr, nc) and comp_id[nr][nc] == -1 and grid[nr][nc] in (1, 3):
                            comp_id[nr][nc] = len(components)
                            stack.append((nr, nc))
                one_cells = [p for p in cells if grid[p[0]][p[1]] == 1]
                three_cells = [p for p in cells if grid[p[0]][p[1]] == 3]
                components.append({"cells": cells, "ones": one_cells, "threes": three_cells})

    # Determine each component's opening direction from its 3s.
    for comp in components:
        dr_dir = dc_dir = 0
        comp["dir"] = None
        if comp["threes"]:
            votes = {}
            for tr, tc in comp["threes"]:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = tr + dr, tc + dc
                    if in_bounds(nr, nc) and grid[nr][nc] == 1:
                        # Direction from 1 toward 3.
                        d = (-dr, -dc)
                        votes[d] = votes.get(d, 0) + 1
            if votes:
                best = max(sorted(votes.keys()), key=lambda d: votes[d])
                comp["dir"] = best
            else:
                if comp["ones"]:
                    ar = sum(p[0] for p in comp["ones"]) / len(comp["ones"])
                    ac = sum(p[1] for p in comp["ones"]) / len(comp["ones"])
                    trs = sum(p[0] for p in comp["threes"]) / len(comp["threes"])
                    tcs = sum(p[1] for p in comp["threes"]) / len(comp["threes"])
                    if abs(trs - ar) > 0.01 and abs(trs - ar) >= abs(tcs - ac):
                        comp["dir"] = ((-1, 0) if trs < ar else (1, 0))
                    elif abs(tcs - ac) > 0.01:
                        comp["dir"] = ((0, -1) if tcs < ac else (0, 1))

    # Preserve the original 2 marker tail and make the 4 head color 2.
    on = [[False] * W for _ in range(H)]
    src = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 2:
                on[r][c] = True
            elif grid[r][c] == 4:
                on[r][c] = True
                src = (r, c)

    queue = []
    queued = [False] * len(components)

    def enqueue(cid):
        if cid is not None and 0 <= cid < len(components) and not queued[cid]:
            queued[cid] = True
            queue.append(cid)

    # Fire the source ray upward from the 4.
    if src is not None:
        sr, sc = src
        r = sr - 1
        while r >= 0:
            cid = comp_id[r][sc]
            if cid != -1:
                enqueue(cid)
                break
            on[r][sc] = True
            r -= 1

    # Propagate through opened components.
    qi = 0
    while qi < len(queue):
        cid = queue[qi]
        qi += 1
        comp = components[cid]

        for r, c in comp["cells"]:
            on[r][c] = True

        direction = comp.get("dir")
        if direction is None:
            continue

        dr, dc = direction
        for tr, tc in comp["threes"]:
            r, c = tr + dr, tc + dc
            while in_bounds(r, c):
                hit = comp_id[r][c]
                if hit != -1:
                    if hit != cid:
                        enqueue(hit)
                        break
                    # If our own protrusion extends farther, continue through it.
                    on[r][c] = True
                else:
                    on[r][c] = True
                r += dr
                c += dc

    return [[2 if on[r][c] else 8 for c in range(W)] for r in range(H)]
